/**
 * Branding + registry URLs for the components library, which lives at
 * tirup.in/components (routes under app/components/, no basePath — this is
 * part of the main site's deployment).
 *
 * Registry JSONs are generated by scripts/build-registry.mjs into
 * public/components/r/. Keep it in sync with this file.
 */
export const SITE = {
  name: "Components",
  url: "https://tirup.in/components",
  email: "contact@tirup.in",
  namespace: "@mehta",
  tagline: "Unique React components I built. Copy the code, own it forever.",
  description:
    "Unique React components I build and post here, with live playgrounds. Copy the code, own it forever.",
} as const

/**
 * Absolute canonical URL for a library route. Routes under app/components/
 * are written WITHOUT the /components prefix (e.g. "/liquid-ascii");
 * this resolves them against the library base.
 */
export const absoluteUrl = (route = "/") => {
  const stem = route === "/" || route === "" ? "" : route
  return `${SITE.url}${stem}`
}

export const registryItemUrl = (name: string) => `${SITE.url}/r/${name}.json`

/** Easiest install: one command, no config. */
export const installCommand = (name: string) => `npx shadcn@latest add ${registryItemUrl(name)}`

/** Alternative: register the namespace once, then `npx shadcn@latest add @mehta/<name>`. */
export const namespaceAddCommand = `npx shadcn@latest registry add ${SITE.namespace}=${SITE.url}/r/{name}.json`

/**
 * The human behind the library (metadata + JSON-LD so search/answer engines
 * connect Tirup Mehta with tirup.in/components).
 */
export const AUTHOR = {
  name: "Tirup Mehta",
  url: "https://tirup.in",
} as const
